// Tests part (c): weighted_avg from average.s.
//
// Input: n (at least 1), then n lines "marks credits". Prints the result.
#include <stdio.h>
#include <stdlib.h>

unsigned long weighted_avg(unsigned long *marks, unsigned long *credits, unsigned long n);

int main(void) {
    unsigned long n;
    if (scanf("%lu", &n) != 1 || n < 1) return 1;
    unsigned long *marks = malloc(n * sizeof *marks), *credits = malloc(n * sizeof *credits);
    for (unsigned long i = 0; i < n; i++)
        if (scanf("%lu %lu", &marks[i], &credits[i]) != 2) return 1;
    printf("weighted_avg = %lu\n", weighted_avg(marks, credits, n));
    return 0;
}
